import json, jupyterlab
meta = {'jupyterlab_version': str(getattr(jupyterlab, '__version__', 'unknown'))}
print('PROBE_META:' + json.dumps(meta))

import json, sys
details = {'cuda_probe_status': 'UNAVAILABLE', 'cuda_api': 'none', 'cuda_library': 'none'}
api_failures = []
supported_library_observed = False
try:
    import torch
    supported_library_observed = True
    details['torch_version'] = str(torch.__version__)
    details['torch_cuda_version'] = str(torch.version.cuda or '')
    if torch.version.cuda:
        try:
            details['torch_cuda_device_count'] = str(int(torch.cuda.device_count()))
            details.update(cuda_probe_status='SUCCESS', cuda_api='torch.cuda.device_count', cuda_library='torch')
        except Exception as exc:
            api_failures.append('torch:' + type(exc).__name__)
except ImportError:
    pass
if details['cuda_probe_status'] != 'SUCCESS':
  try:
    import tensorflow as tf
    supported_library_observed = True
    details['tensorflow_version'] = str(tf.__version__)
    if bool(tf.test.is_built_with_cuda()):
        try:
            details['tensorflow_gpu_devices'] = str(len(tf.config.list_physical_devices('GPU')))
            details.update(cuda_probe_status='SUCCESS', cuda_api='tf.config.list_physical_devices', cuda_library='tensorflow')
        except Exception as exc:
            api_failures.append('tensorflow:' + type(exc).__name__)
  except (ImportError, AttributeError):
    pass
if details['cuda_probe_status'] != 'SUCCESS' and api_failures:
    details['cuda_probe_status'] = 'FAILURE'
    details['cuda_api_failures'] = ','.join(api_failures)
elif details['cuda_probe_status'] != 'SUCCESS' and supported_library_observed:
    details['unavailable_reason'] = 'supported_libraries_have_no_cuda_userspace_build'
elif details['cuda_probe_status'] != 'SUCCESS':
    details['unavailable_reason'] = 'no_supported_cuda_library_importable'
print('PROBE_META:' + json.dumps(details))
sys.exit(0 if details['cuda_probe_status'] == 'SUCCESS' else (4 if details['cuda_probe_status'] == 'FAILURE' else 3))

